CREATE OR REPLACE PROCEDURE sp(arg1 NUMBER, arg2 VARCHAR2, arg3 NUMBER, arg4 NUMBER) IS
  v_total  NUMBER := 0;
  v_max_no  NUMBER;
  v_new_no  NUMBER;
BEGIN
  FOR r IN (
    SELECT "No", "Grape", "Winery", "Price", "Score", "Cases"
    FROM "wine"
    WHERE "Score" >= arg1
    ORDER BY "No"
  ) LOOP
    v_total := v_total + r."Price";

    IF instr(r."Grape", 'prefix_') = 1 THEN
      UPDATE "wine"
      SET "Price" = arg3
      WHERE "No" = r."No";
    ELSIF r."No" < arg4 THEN
      DELETE FROM "wine"
      WHERE "No" = r."No";
    ELSIF r."Winery" = 'Twomey' THEN
      UPDATE "wine"
      SET "Price" = arg3 + r."Price"
      WHERE "No" = r."No";
    ELSIF r."Cases" > r."Score" THEN
      UPDATE "wine"
      SET "Price" = arg3 + r."Price"
      WHERE "No" = r."No";
    ELSE
      UPDATE "wine"
      SET "Price" = 2 * arg3
      WHERE "No" = r."No";
    END IF;
  END LOOP;

  SELECT MAX("No")
  INTO v_max_no
  FROM "wine";

  IF v_max_no IS NULL THEN
    v_new_no := 1;
  ELSE
    v_new_no := v_max_no + 1;
  END IF;

  INSERT INTO "wine" ("No", "Grape", "Score", "Price")
  VALUES (
    v_new_no,
    'prefix_' || arg2,
    arg1 + 1,
    CASE WHEN v_total > arg4 THEN arg3 + 1 ELSE arg3 END
  );
END sp;
/

